const now = new Date();
const batchId = (typeof crypto !== 'undefined' && crypto.randomUUID)
  ? crypto.randomUUID()
  : `${now.toISOString().replace(/[:.]/g, '-')}-${Math.random().toString(36).slice(2, 10)}`;
return [{
  json: {
    batch_id: batchId,
    started_at: now.toISOString(),
    batch_size: Number($env.RAG_GRAPH_EXTRACT_BATCH_SIZE) || 20,
    max_age_hours: Number($env.RAG_GRAPH_EXTRACT_MAX_AGE_HOURS) || 168
  }
}];

const result = $('Run Graph Extract Batch').first()?.json ?? {};
const prep = $('Prepare Batch ID').first()?.json ?? {};
const now = new Date().toISOString();

const summary = {
  timestamp: now,
  workflow: 'WF_GRAPH_EXTRACT_NIGHTLY',
  batch_id: result.batch_id || prep.batch_id,
  judge_model: result.judge_model,
  candidates: result.candidates ?? 0,
  processed: result.processed ?? 0,
  failed: result.failed ?? 0,
  nodes_added: result.nodes_added ?? 0,
  edges_added: result.edges_added ?? 0,
  edges_skipped: result.edges_skipped ?? 0,
  duration_ms: result.duration_ms ?? 0,
  failures_sample: (result.failures || []).slice(0, 5)
};

const total = summary.processed + summary.failed;
if (total === 0) {
  summary.severity = 'info';
  summary.message = 'Graph extract queue is caught up — no candidates.';
} else if (summary.failed > 0 && summary.failed >= total * 0.2) {
  summary.severity = 'warn';
  summary.message = `Graph extract batch had ${summary.failed}/${total} failures.`;
} else {
  summary.severity = 'info';
  summary.message = `Graph extract batch ok: ${summary.processed}/${summary.candidates} runs, ${summary.nodes_added} nodes + ${summary.edges_added} edges added (${summary.edges_skipped} edges skipped).`;
}

return [{ json: summary }];
